// Turns web/chat_page.html into lib/web/embedded_page.dart (gzip + base64) so
// the compiled server carries its page and needs no file beside it.
// Run by tool/sync_web_chat.sh; the generated file is committed.
import 'dart:convert';
import 'dart:io';

void main() {
  final html = File('web/chat_page.html').readAsBytesSync();
  final b64 = base64.encode(gzip.encode(html));
  final lines = <String>[];
  for (var i = 0; i < b64.length; i += 76) {
    lines.add(
      "    '${b64.substring(i, i + 76 > b64.length ? b64.length : i + 76)}'",
    );
  }
  File('lib/web/embedded_page.dart').writeAsStringSync('''
// GENERATED by tool/embed_page.dart from web/chat_page.html. Do not edit.
import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

/// The web chat page, compiled into the program.
Uint8List embeddedPage() => Uint8List.fromList(gzip.decode(base64.decode(_gz)));

const _gz =
${lines.join('\n')};
''');
  stdout.writeln(
    'lib/web/embedded_page.dart: ${html.length} -> ${b64.length} chars',
  );
}
